<script setup>
import RecycleBin from "./RecycleBin.vue";
import {useUiText} from "../ui-text";
const ui=useUiText();

import {fuzzyMatch} from '../../shared/search.mjs';
import {ref,computed,onMounted} from 'vue';
import {PanelsTopLeft,RefreshCw,Trash2,Undo2,X,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
const s=useStudio(),emit=defineEmits(['close']),query=ref(''),trash=ref([]),refreshing=ref(false),deleting=ref(null),deleteRelated=ref(false),working=ref(false),showTrash=ref(false);
const projects=computed(()=>s.projects.filter(p=>fuzzyMatch(query.value,p.name)));
async function refresh(){refreshing.value=true;try{await s.refreshCollections();trash.value=await api('projects/trash');}finally{refreshing.value=false;}}
async function remove(){if(working.value)return;working.value=true;try{const result=await s.deleteProject(deleting.value.id,{deleteRelated:deleteRelated.value});trash.value=result.trash;deleting.value=null;s.notify('项目已移入本地回收区');}finally{working.value=false;}}
async function restore(p){if(working.value)return;working.value=true;try{const d=await api('projects/restore',{id:p.id});s.projects=d.projects;if(d.config)s.config=d.config;trash.value=d.trash;s.notify('已恢复 '+p.name);}finally{working.value=false;}}
onMounted(()=>s.action(refresh));
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal project-browser" role="dialog" :aria-label="ui(&quot;本地漫画项目&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :title="ui(&quot;关闭项目列表&quot;)" @click="emit('close')"><X :size="19"/></button></div><div class="modal-title"><h2>{{ui("本地漫画项目")}}</h2><button class="secondary" :disabled="refreshing" :aria-busy="refreshing" @click="s.action(refresh)"><RefreshCw :size="15"/>{{ui("刷新项目列表")}}</button></div><input v-model="query" :placeholder="ui(&quot;模糊查找项目名称&quot;)" :aria-label="ui(&quot;模糊查找项目名称&quot;)"/><div class="project-browser-list"><div v-for="p in projects" :key="p.id" class="project-browser-row"><button class="project-entry" :title="p.name" @click="s.action(async()=>{await s.openProject(p.id);emit('close')})"><PanelsTopLeft :size="18"/><strong>{{p.name}}</strong><span>{{ui(p.pages)}}{{s.t(' 页',' pages')}}</span><small>{{ui(new Date(p.updated).toLocaleString())}}</small></button><button class="icon-button danger" :title="ui('删除项目：')+p.name" :aria-label="ui('删除项目：')+p.name" @click="deleteRelated=false;deleting=p"><Trash2 :size="17"/></button></div><p v-if="!projects.length" class="empty">{{ui(query?'没有匹配的项目':'暂无已保存项目')}}</p></div><button class="quiet" @click="showTrash=!showTrash"><Trash2 :size="14"/>{{ui("本地回收区（")}}{{trash.length}}{{s.t('）',')')}}</button><RecycleBin v-if="showTrash" initial="projects" @close="showTrash=false" @changed="s.action(refresh)"/></section><div v-if="deleting" class="modal-backdrop" @click.self="!working&&(deleting=null)"><section class="modal confirm-modal" role="dialog" :aria-label="ui(&quot;确认删除项目&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭项目删除确认&quot;)" @click="deleting=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui("删除项目")}}</h2></div><p>{{ui("将“")}}{{deleting.name}}{{ui("”移入本地回收区？可在项目列表中恢复。")}}</p><fieldset class="project-delete-options" :disabled="working"><legend>{{s.t('关联内容处理方式','Related content')}}</legend><label><input v-model="deleteRelated" type="radio" :value="false" name="project-delete-content"/><span><strong>{{s.t('保留图片','Keep images')}}</strong><small>{{s.t('只移除项目，图片继续保留在画廊中。','Remove the project and keep its images in the gallery.')}}</small></span></label><label><input v-model="deleteRelated" type="radio" :value="true" name="project-delete-content"/><span><strong>{{s.t('一并删除所有关联内容','Delete all related content')}}</strong><small>{{s.t('将关联图片、编辑草稿和项目资源移入回收区，其他项目正在使用的图片会保留。','Move related images, editing drafts and project resources to the recycle bin. Images used by other projects are kept.')}}</small></span></label></fieldset><p class="muted">{{s.t('可从项目回收区恢复项目及其关联内容。','Restore the project and its related content from the project recycle bin.')}}</p><div class="button-row"><button class="secondary" :disabled="working" @click="deleting=null">{{ui("取消")}}</button><button class="primary" :disabled="working" @click="s.action(remove)"><LoaderCircle v-if="working" class="spin" :size="15"/><Trash2 v-else :size="15"/>{{ui("移入回收区")}}</button></div></section></div></div></template>
